def make_full_spot_object(spot_tuple):
    sid, name_en, name_ja_base, category, desc_ja, desc_en, tip_ja, tip_en, price_str, lat, lng, zone, kids, rain, shopping, free = spot_tuple
    full_name_ja = f"{name_en}（{name_ja_base}）"
    
    if free or "無料" in price_str or "Free" in price_str:
        p_ja, p_en, p_es, p_zh, p_fr, p_de = price_str if "無料" in price_str else "散策無料", "Free Entry", "Acceso libre", "免费参观", "Accès gratuit", "Freier Zugang"
        is_free = True
    else:
        clean = price_str.replace("料金:", "").replace("入場料:", "").strip()
        p_ja, p_en, p_es, p_zh, p_fr, p_de = f"料金: {clean}", f"Entry: {clean}", f"Entrada: {clean}", f"门票：{clean}", f"Entrée : {clean}", f"Eintritt: {clean}"
        is_free = False

    return {
        "id": sid,
        "name": full_name_ja,
        "category": category,
        "rating": "★4.7",
        "locationZone": zone,
        "lat": round(lat, 4),
        "lng": round(lng, 4),
        "kids": kids,
        "rain": rain,
        "shopping": shopping,
        "free": is_free,
        "family": True,
        "adult": True,
        "image": "",
        "wikiImage": "",
        "hasWiki": True,
        "name_en": name_en,
        "name_ja": full_name_ja,
        "name_es": name_en,
        "name_zh": name_en,
        "name_fr": name_en,
        "name_de": name_en,
        "desc_en": desc_en,
        "desc_ja": desc_ja,
        "desc_es": desc_en,
        "desc_zh": desc_ja,
        "desc_fr": desc_en,
        "desc_de": desc_en,
        "tip_en": tip_en,
        "tip_ja": tip_ja,
        "tip_es": tip_en,
        "tip_zh": tip_ja,
        "tip_fr": tip_en,
        "tip_de": tip_en,
        "price_ja": p_ja,
        "price_en": p_en,
        "price_es": p_es,
        "price_zh": p_zh,
        "price_fr": p_fr,
        "price_de": p_de
    }

def run_compiler():
    final_spots = [make_full_spot_object(s) for s in spots_data]
    
    filepath = os.path.join(cities_dir, "the_hague.json")
    out_obj = {
        "city": "The Hague",
        "country": "Netherlands",
        "city_ja": "ハーグ",
        "country_ja": "オランダ",
        "spots": final_spots
    }
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(out_obj, f, indent=2, ensure_ascii=False)

    print(f"🎉 Successfully compiled the_hague.json with {len(final_spots)} verified spots!")

if __name__ == '__main__':
    run_compiler()
